draw:
var cx = W * 0.5, cy = H * 0.5;
var R3 = Math.min(W, H) * 0.42;   // outer surface of shell
var R2 = R3 * 0.76;               // inner surface of shell (cavity wall)
var q = p.qc, Qs = p.qshell;

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.textAlign = "center";

// the metal of the shell
ctx.fillStyle = C.faint;
ctx.beginPath();
ctx.arc(cx, cy, R3, 0, 6.2832);
ctx.arc(cx, cy, R2, 0, 6.2832, true);
ctx.fill();

ctx.strokeStyle = C.rule;
ctx.lineWidth = 1;
ctx.beginPath(); ctx.arc(cx, cy, R3, 0, 6.2832); ctx.stroke();
ctx.beginPath(); ctx.arc(cx, cy, R2, 0, 6.2832); ctx.stroke();

// Gaussian surface drawn inside the metal
var Rg = (R2 + R3) * 0.5;
ctx.strokeStyle = C.accent;
ctx.setLineDash([4, 4]);
ctx.lineWidth = 1.5;
ctx.beginPath(); ctx.arc(cx, cy, Rg, 0, 6.2832); ctx.stroke();
ctx.setLineDash([]);

// field lines in the cavity: radial, count set by q
var nIn = Math.max(0, Math.round(Math.abs(q) * 2));
ctx.strokeStyle = C.figure;
ctx.lineWidth = 1.2;
for (var i = 0; i < nIn; i++) {
  var a = i * 6.2832 / Math.max(1, nIn) + 0.15;
  var r0 = 10, r1 = R2 - 2;
  var sgn = q >= 0 ? 1 : -1;
  ctx.beginPath();
  ctx.moveTo(cx + Math.cos(a) * r0, cy + Math.sin(a) * r0);
  ctx.lineTo(cx + Math.cos(a) * r1, cy + Math.sin(a) * r1);
  ctx.stroke();
  var am = (r0 + r1) * 0.5 + sgn * 6;
  ctx.beginPath();
  ctx.moveTo(cx + Math.cos(a) * am, cy + Math.sin(a) * am);
  ctx.lineTo(cx + Math.cos(a) * (am - sgn * 7) - Math.sin(a) * 4, cy + Math.sin(a) * (am - sgn * 7) + Math.cos(a) * 4);
  ctx.lineTo(cx + Math.cos(a) * (am - sgn * 7) + Math.sin(a) * 4, cy + Math.sin(a) * (am - sgn * 7) - Math.cos(a) * 4);
  ctx.closePath();
  ctx.fillStyle = C.figure;
  ctx.fill();
}

// field lines outside, count set by net enclosed charge q + Qs
var qOut = q + Qs;
var nOut = Math.max(0, Math.round(Math.abs(qOut) * 2));
ctx.strokeStyle = C.figure;
for (var j = 0; j < nOut; j++) {
  var b = j * 6.2832 / Math.max(1, nOut) + 0.4;
  var s0 = R3 + 2, s1 = R3 + Math.min(W, H) * 0.12;
  ctx.beginPath();
  ctx.moveTo(cx + Math.cos(b) * s0, cy + Math.sin(b) * s0);
  ctx.lineTo(cx + Math.cos(b) * s1, cy + Math.sin(b) * s1);
  ctx.stroke();
}

// charges
ctx.fillStyle = C.accent;
ctx.beginPath(); ctx.arc(cx, cy, 8, 0, 6.2832); ctx.fill();
ctx.fillStyle = C.paper;
ctx.fillText(q >= 0 ? "+" : "-", cx, cy + 4);

// surface charge marks
function marks(radius, amount, inward) {
  var n = Math.min(18, Math.max(0, Math.round(Math.abs(amount) * 1.6)));
  ctx.fillStyle = C.ink;
  for (var m = 0; m < n; m++) {
    var a2 = m * 6.2832 / Math.max(1, n) + 0.05;
    var rr = radius + (inward ? 9 : -9);
    ctx.fillText(amount >= 0 ? "+" : "-", cx + Math.cos(a2) * rr, cy + Math.sin(a2) * rr + 4);
  }
}
marks(R2, -q, false);
marks(R3, qOut, true);

ctx.fillStyle = C.ink;
ctx.textAlign = "left";
ctx.fillText("cavity wall: " + (-q).toFixed(1) + " nC", 8, 16);
ctx.fillText("outer surface: " + qOut.toFixed(1) + " nC", 8, 32);
ctx.textAlign = "right";
ctx.fillStyle = C.accent;
ctx.fillText("Gaussian surface inside the metal encloses 0", W - 8, H - 8);

out.note = "inner wall " + (-q).toFixed(1) + " nC, outer surface " + qOut.toFixed(1) + " nC, field outside is that of " + qOut.toFixed(1) + " nC at the centre";
